"""``docs/architecture/capabilities.md``: the catalogue as tables, a dependency graph and a gap list. Every
count on the page is computed here from the catalogue."""

from __future__ import annotations

from collections import Counter
from collections.abc import Iterator
from typing import Any

from .catalogue import Catalogue, phase_label

GENERATED_NOTICE = (
    "Generated by tools/catalogue (`just capabilities --write`) from capabilities.yaml. Do not edit."
)
STATUSES = ("built", "partial", "planned", "proposed", "dropped")
TOOL_STATUSES = ("built", "planned", "unresolved", "proposed", "dropped")
"""A tool or CLI command is never partial, and only a tool can be unresolved."""
NOT_DEFINED = "not yet defined"
_CLASSES = (
    "classDef built fill:#e8f5e9,stroke:#2e7d32,stroke-width:2px,color:#1b1b1b",
    "classDef partial fill:#f1faf3,stroke:#2e7d32,stroke-width:2px,stroke-dasharray:6 3,color:#1b1b1b",
    "classDef planned fill:#ffffff,stroke:#616161,stroke-width:1px,stroke-dasharray:6 4,color:#1b1b1b",
    "classDef open fill:#ffebee,stroke:#c62828,stroke-width:2px,stroke-dasharray:2 3,color:#1b1b1b",
    "classDef proposed fill:#f3e5f5,stroke:#6a1b9a,stroke-width:1px,stroke-dasharray:2 3,color:#1b1b1b",
    "classDef dropped fill:#eeeeee,stroke:#888888,stroke-dasharray:4 3,color:#666666",
)
_ON_MAIN = ("built", "partial")


def render_page(catalogue: Catalogue) -> str:
    sections = (
        _introduction(catalogue),
        _capability_tables(catalogue),
        _graph(catalogue),
        _tool_catalogue(catalogue),
        _mcp_surface(catalogue),
        _cli_table(catalogue),
        _prototype_table(catalogue),
        _gaps(catalogue),
        _open_questions(catalogue),
        _capability_details(catalogue),
    )
    lines = ["# Capability catalogue", "", GENERATED_NOTICE, ""]
    for section in sections:
        lines += [*section, ""]
    return "\n".join(lines).rstrip("\n") + "\n"


def _phases(catalogue: Catalogue) -> list[int | None]:
    phases = {item["phase"] for item in catalogue.capabilities}
    return sorted(phases, key=lambda phase: (phase is None, phase or 0))


def _code(text: str) -> str:
    return f"`{text}`"


def _cell(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def _codes(items: list[str]) -> str:
    return ", ".join(_code(item) for item in items) if items else "–"


def _link(capability_id: str) -> str:
    return f"[{capability_id}](#{capability_id})"


def _introduction(catalogue: Catalogue) -> list[str]:
    lines = [
        "The general model of benchhand: each capability (a feature), the MCP tools and CLI commands that "
        "expose it, and the prototype commands they replace. Per-feature specs split it into work blocks.",
        "",
        "- **built**: on `main`; its evidence points at the code. **partial**: part of it is on `main`; "
        "its note says what is left.",
        "- **planned**: a phase of the design plan's Steps builds it. **proposed**: no source plans it. "
        "A proposed name comes from this catalogue (`catalogue`), for a prototype command or a gap the "
        "plan implies, or from the CAD-libraries study (`study`), whose reports aren't in this repository.",
        "- `P2` is Phase 2 of the plan's Steps. `no phase` means no phase delivers it; an open question "
        "says why.",
        "- A capability's status is its core's. Each tool and CLI command has its own status and phase. A tool "
        "is **unresolved** when a source names it only in an example and an open question asks whether it "
        "exists; it has no phase until that is answered.",
        "",
        "| Phase | Capabilities | " + " | ".join(STATUSES) + " |",
        "|---|---|" + "---|" * len(STATUSES),
    ]
    for phase in _phases(catalogue):
        counts = Counter(item["status"] for item in catalogue.capabilities if item["phase"] == phase)
        cells = " | ".join(str(counts[status]) for status in STATUSES)
        lines.append(f"| {phase_label(phase)} | {sum(counts.values())} | {cells} |")
    total = Counter(item["status"] for item in catalogue.capabilities)
    cells = " | ".join(str(total[status]) for status in STATUSES)
    lines.append(f"| **all** | **{len(catalogue.capabilities)}** | {cells} |")
    tools = Counter(tool["status"] for tool in catalogue.tools)
    commands = Counter(command["status"] for command in catalogue.cli)
    return [
        *lines,
        "",
        f"MCP tools: {len(catalogue.tools)} ({_counted(tools)}). "
        f"CLI commands: {len(catalogue.cli)} ({_counted(commands)}). "
        f"Prototype commands: {len(catalogue.prototype_commands)}. "
        f"Open questions: {len(catalogue.open_questions)}.",
    ]


def _counted(counts: Counter[str]) -> str:
    return ", ".join(f"{counts[status]} {status}" for status in TOOL_STATUSES if counts[status])


def _capability_tables(catalogue: Catalogue) -> list[str]:
    lines = ["## Capabilities by phase", ""]
    for phase in _phases(catalogue):
        lines += [
            f"### {phase_label(phase)}",
            "",
            "| Capability | Title | Layer | Container | Status | Owner | Tools | CLI |",
            "|---|---|---|---|---|---|---|---|",
        ]
        for item in (item for item in catalogue.capabilities if item["phase"] == phase):
            tools = len(catalogue.tools_of(item["id"]))
            commands = len(catalogue.cli_of(item["id"]))
            lines.append(
                f"| {_link(item['id'])} | {_cell(item['title'])} | {item['layer']} | {_code(item['container'])} "
                f"| {item['status']} | {_codes(item['owner'])} | {tools} | {commands} |"
            )
        lines.append("")
    return lines[:-1]


def _node(capability_id: str) -> str:
    return capability_id.replace("-", "_")


def _style(item: dict[str, Any]) -> str:
    if item["status"] in ("proposed", "dropped") or item["status"] in _ON_MAIN:
        return item["status"]
    return "open" if item["phase"] is None else "planned"


def _graph(catalogue: Catalogue) -> list[str]:
    lines = [
        "## Dependency graph",
        "",
        "An arrow points from a capability to one it depends on. A solid box or arrow is on `main`: green "
        "is built, pale green with a dashed border is partial, and a solid arrow joins two of them. A dashed "
        "box is planned, with its phase in the label; red and dotted has no phase; purple and dotted is "
        "proposed. A dashed arrow is not implemented, and its nodes give the phase and status. It is labelled "
        "`proposed` when either end is proposed, and `no phase` when either end has no phase.",
        "",
        "```mermaid",
        "flowchart LR",
    ]
    for phase in _phases(catalogue):
        lines.append(f'  subgraph {_node("phase-" + phase_label(phase))}["{phase_label(phase)}"]')
        for item in (item for item in catalogue.capabilities if item["phase"] == phase):
            label = f"{item['title']}<br/>{phase_label(item['phase'])}, {item['status']}".replace('"', "'")
            lines.append(f'    {_node(item["id"])}["{label}"]:::{_style(item)}')
        lines.append("  end")
    for item in catalogue.capabilities:
        for target in item.get("depends_on", []):
            lines.append(f"  {_node(item['id'])} {_edge(item, catalogue.capability(target))} {_node(target)}")
    return [*lines, *(f"  {definition}" for definition in _CLASSES), "```"]


def _edge(source: dict[str, Any], target: dict[str, Any]) -> str:
    ends = (source, target)
    if all(end["status"] in _ON_MAIN for end in ends):
        return "-->"
    if any(end["status"] == "proposed" for end in ends):
        return "-.->|proposed|"
    if any(end["phase"] is None for end in ends):
        return "-.->|no phase|"
    return "-.->"


def _source(source: dict[str, str]) -> str:
    return f"{source['kind']}: {_code(source['ref'])}"


def _tool_catalogue(catalogue: Catalogue) -> list[str]:
    lines = [
        "## MCP tools",
        "",
        "Every tool returns the result envelope (`envelope/envelope.schema.json`); *output* is its payload. "
        "*Envelope* `sync-or-job` returns `ok`, or `pending` with a job handle when the work would pass "
        "the long-call threshold (ADR-0018). *Gate* `unspecified` means the tool writes and no source says "
        "whether the call is checked against the stage.",
        "",
        "| Tool | Capability | Access | Input | Output | Envelope | Gate | Phase | Status | Source | Replaces |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for tool in sorted(catalogue.tools, key=lambda tool: tool["name"]):
        lines.append(
            f"| {_code(tool['name'])} | {_link(tool['capability'])} | {tool['access']} | {_contract(tool['input'])} "
            f"| {_contract(tool['output'])} | {tool['envelope']} | {tool['gate']} | {phase_label(tool['phase'])} "
            f"| {tool['status']} | {_cell(_source(tool['source']))} | {_codes(tool.get('replaces', []))} |"
        )
    return lines


def _contract(reference: str) -> str:
    return reference if reference == NOT_DEFINED else _code(reference)


def _mcp_surface(catalogue: Catalogue) -> list[str]:
    lines = [
        "## MCP resources, prompts and Apps",
        "",
        "ADR-0018 makes a tool the baseline for readable content: each resource, prompt and App is an "
        "enhancement over a tool that returns the same content. *Baseline* names those tools, and **missing** "
        "says what no tool returns yet. An App form is an MCP App, not MCP form elicitation, which ADR-0018 drops.",
        "",
        "| Capability | Resources | Prompts | Apps | Baseline | Phase | Sources |",
        "|---|---|---|---|---|---|---|",
    ]
    for item in catalogue.capabilities:
        surface = item.get("mcp")
        if surface:
            lines.append(
                f"| {_link(item['id'])} | {_codes(surface.get('resources', []))} "
                f"| {_codes(surface.get('prompts', []))} | {_codes(surface.get('apps', []))} "
                f"| {_cell(_baseline(surface))} | {phase_label(surface['phase'])} "
                f"| {_cell('; '.join(_source(source) for source in surface['sources']))} |"
            )
    return lines


def _baseline(surface: dict[str, Any]) -> str:
    missing = f"**missing:** {surface['baseline_missing']}" if "baseline_missing" in surface else ""
    tools = ", ".join(_code(name) for name in surface["baseline"])
    return "; ".join(part for part in (tools, missing) if part)


def _cli_table(catalogue: Catalogue) -> list[str]:
    lines = [
        "## CLI commands",
        "",
        "*Role* is the command's place under ADR-0001. `read-only-adapter` is the CAD-libraries study's "
        "proposed ADR-0001 amendment: a read-only command over the same core as an MCP tool.",
        "",
        "| Command | Capability | Status | Phase | MCP equivalent | Access | Role | Source |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for command in catalogue.cli:
        lines.append(
            f"| {_code('benchhand ' + command['name'])} | {_link(command['capability'])} | {command['status']} "
            f"| {phase_label(command['phase'])} | {_codes(command.get('mcp', []))} | {command['access']} "
            f"| {command['role']} | {_cell(_source(command['source']))} |"
        )
    return lines


def _replacing(catalogue: Catalogue, command: str) -> list[str]:
    return [tool["name"] for tool in catalogue.tools if command in tool.get("replaces", [])]


def _prototype_table(catalogue: Catalogue) -> list[str]:
    lines = [
        "## Prototype commands",
        "",
        "Every command line the prototype can run at the pin, as `prototype-inventory.json` lists them, and the "
        "flag-only modes its skills told the agent to run through `cad-flow/scripts/run.py`. `just capabilities` "
        "checks the list against the inventory both ways.",
        "",
        "| Command | Prototype path | Capability | Replaced by | Note |",
        "|---|---|---|---|---|",
    ]
    for command in catalogue.prototype_commands:
        capability = _link(command["capability"]) if command["capability"] else "–"
        lines.append(
            f"| {_code(command['command'])} | {_code(command['path'])} | {capability} "
            f"| {_codes(_replacing(catalogue, command['command']))} | {_cell(command.get('note', ''))} |"
        )
    return lines


def _gaps(catalogue: Catalogue) -> list[str]:
    lines = ["## Gaps", ""]
    for title, entries in _gap_lists(catalogue):
        lines += [f"### {title} ({len(entries)})", ""]
        lines += [*entries] if entries else ["None."]
        lines.append("")
    return lines[:-1]


def _gap_lists(catalogue: Catalogue) -> Iterator[tuple[str, list[str]]]:
    toolless = [item for item in catalogue.capabilities if not catalogue.tools_of(item["id"])]
    yield (
        "Capabilities with no MCP tool",
        [
            f"- {_link(item['id'])} ({phase_label(item['phase'])}, {item['status']})"
            for item in toolless
            if "no_tool_reason" not in item
        ],
    )
    yield (
        "Capabilities with no MCP tool by design",
        [f"- {_link(item['id'])}: {item['no_tool_reason']}" for item in toolless if "no_tool_reason" in item],
    )
    yield (
        "MCP surfaces with a missing baseline",
        [
            f"- {_link(item['id'])}: {item['mcp']['baseline_missing']}"
            for item in catalogue.capabilities
            if "baseline_missing" in item.get("mcp", {})
        ],
    )
    yield (
        "Tools with no contract",
        [
            f"- {_code(tool['name'])}: {_undefined(tool)}"
            for tool in sorted(catalogue.tools, key=lambda tool: tool["name"])
            if NOT_DEFINED in (tool["input"], tool["output"])
        ],
    )
    yield (
        "Prototype commands with no capability",
        [
            f"- {_code(command['command'])} ({_code(command['path'])})"
            for command in catalogue.prototype_commands
            if not command["capability"]
        ],
    )
    yield (
        "Prototype commands no tool replaces",
        [
            f"- {_code(command['command'])} ({_link(command['capability'])})"
            for command in catalogue.prototype_commands
            if command["capability"] and not _replacing(catalogue, command["command"])
        ],
    )
    yield "Dependencies on a later phase", list(_phase_order(catalogue))


def _undefined(tool: dict[str, Any]) -> str:
    return " and ".join(field for field in ("input", "output") if tool[field] == NOT_DEFINED)


def _phase_order(catalogue: Catalogue) -> Iterator[str]:
    """A capability that depends on one a later phase builds, or on one with no phase."""
    for item in catalogue.capabilities:
        for target in (catalogue.capability(name) for name in item.get("depends_on", [])):
            if item["phase"] is not None and (target["phase"] is None or target["phase"] > item["phase"]):
                yield (
                    f"- {_link(item['id'])} ({phase_label(item['phase'])}) depends on "
                    f"{_link(target['id'])} ({phase_label(target['phase'])})"
                )


def _open_questions(catalogue: Catalogue) -> list[str]:
    lines = [
        "## Open questions",
        "",
        "`existing`: a source already lists it as open. `catalogue`: found while building this catalogue, "
        "mostly where two sources disagree; each position quotes one source.",
        "",
    ]
    for question in catalogue.open_questions:
        cited = [
            where for where, item in _citers(catalogue) if question["id"] in item.get("open_questions", [])
        ]
        lines += [
            f"### {question['id']}",
            "",
            f"{question['question']} ({question['origin']})",
            "",
            f"- Pointers: {_codes(question['pointers'])}",
            *(
                f"- {_code(position['source'])}: {position['says']}"
                for position in question.get("positions", [])
            ),
            f"- Cited by: {', '.join(cited)}",
            "",
        ]
    return lines[:-1]


def _citers(catalogue: Catalogue) -> Iterator[tuple[str, dict[str, Any]]]:
    yield from ((_link(item["id"]), item) for item in catalogue.capabilities)
    yield from ((_code(item["name"]), item) for item in catalogue.tools)
    yield from ((_code("benchhand " + item["name"]), item) for item in catalogue.cli)


def _capability_details(catalogue: Catalogue) -> list[str]:
    lines = ["## Capability details", ""]
    for item in catalogue.capabilities:
        lines += [
            f"### {item['id']}",
            "",
            f"**{item['title']}.** {item['purpose']}",
            "",
            *_facts(catalogue, item),
            "",
        ]
    return lines[:-1]


def _facts(catalogue: Catalogue, item: dict[str, Any]) -> list[str]:
    facts = [
        f"- Layer and container: {item['layer']}, {_code(item['container'])}",
        f"- Phase and status: {phase_label(item['phase'])}, {item['status']}",
        f"- Owner: {_codes(item['owner'])}",
        f"- Contracts: {_codes(item.get('contracts', []))}",
        f"- MCP tools: {_codes([tool['name'] for tool in catalogue.tools_of(item['id'])])}",
        f"- CLI: {_codes(['benchhand ' + command['name'] for command in catalogue.cli_of(item['id'])])}",
        f"- Depends on: {', '.join(_link(name) for name in item.get('depends_on', [])) or '–'}",
        f"- ADRs: {', '.join(f'ADR-{number:04d}' for number in item['adrs']) or '–'}",
    ]
    optional = (
        ("Evidence", _codes(item.get("evidence", []))),
        ("Note", item.get("note", "")),
        ("Source", _source(item["source"]) if "source" in item else ""),
        ("Contracts not yet published", "; ".join(item.get("contracts_planned", []))),
        ("Prototype", _codes(item.get("prototype", []))),
        ("Open questions", ", ".join(f"[{name}](#{name})" for name in item.get("open_questions", []))),
    )
    return facts + [f"- {label}: {value}" for label, value in optional if value and value != "–"]
